const std = @import("std");

fn floodFill(grid: []u8, width: usize, x: usize, y: usize, newColor: u8, oldColor: u8) void {
    const idx = y * width + x;
    if (idx >= grid.len) return;
    if (grid[idx] != oldColor) return;
    grid[idx] = newColor;
    if (x > 0) floodFill(grid, width, x - 1, y, newColor, oldColor);
    if (x + 1 < width) floodFill(grid, width, x + 1, y, newColor, oldColor);
    if (y > 0) floodFill(grid, width, x, y - 1, newColor, oldColor);
    floodFill(grid, width, x, y + 1, newColor, oldColor);
}

pub fn main() !void {
    var grid = [_]u8{ 1, 1, 1, 2, 2, 1, 1, 0, 2, 2, 0, 1, 0, 0, 2, 0, 0, 0, 2, 2 };
    const width: usize = 5;
    floodFill(grid, width, 1, 1, 3, 1);
    for (grid) |val| std.debug.print("{} ", .{val});
    std.debug.print("\n", .{});
}
